/bin/bash -lc "python3 -c \"
from PIL import Image
import numpy as np, colorsys
a = np.array(Image.open('first_frame.png')).astype(int)
h,w,_ = a.shape
small = np.array(Image.open('first_frame.png').resize((85,48)))
out=[]
for row in small:
    line=''
    for r,g,b in row:
        hh,ss,vv = colorsys.rgb_to_hsv(r/255,g/255,b/255)
        if ss < 0.18:
            line += ' .:-=+'[min(5,int(vv*6))]
        elif hh < 0.035:
            line += 'R'
        elif hh < 0.075:
            line += 'o'
        elif hh < 0.11:
            line += 'O'
        elif hh < 0.22:
            line += 'Y'
        else:
            line += 'G'
    out.append(line)
print('\\n'.join(out))
\""
